def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    alive_opps = [o for o in opponents_status.values() if o.get('alive')]
    if not alive_opps:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    # Read yesterday bids only (immediate reaction)
    prev_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                prev_bids.append(float(bid))
            except Exception:
                pass

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))

    # Determine pressure from yesterday
    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Supply-based aggressiveness: medium scenario tends to reward matching strong bids
    # Normalize supply to [0,1]
    denom = (MAX_SUPPLY - MIN_SUPPLY)
    norm = 0.5
    if denom != 0:
        norm = (supply - MIN_SUPPLY) / denom
    if norm < 0.0:
        norm = 0.0
    if norm > 1.0:
        norm = 1.0

    # If strong opponents were bidding near/above ~80 yesterday, we match a fraction.
    # Alex/David survived with ~80 bids.
    if highest_prev_bid >= 75.0:
        # Keep enough budget cushion; if low HP, bid more.
        if my_hp <= 2.0:
            target = DAILY_SALARY * (0.95 - 0.15 * norm)
        elif my_hp <= 4.0:
            target = DAILY_SALARY * (0.75 - 0.10 * norm)
        else:
            target = DAILY_SALARY * (0.70 - 0.08 * norm)
    else:
        # If no strong pressure, still bid to secure water.
        if my_hp <= 2.0:
            target = DAILY_SALARY * 0.85
        elif my_hp <= 4.0:
            target = DAILY_SALARY * 0.65
        else:
            target = DAILY_SALARY * (0.50 + 0.10 * norm)

    # Ensure we don't overspend; also avoid bidding too low when supply is enough.
    # Cap at a fraction of budget to keep future flexibility.
    budget_cap = my_budget * 0.55 if my_budget > 0 else 0.0
    # But if HP is critical, allow higher spend.
    if my_hp <= 2.0:
        budget_cap = my_budget * 0.85

    bid = min(my_budget, target, budget_cap)

    # Minimum bid floor: if supply is moderate and we have budget, bid at least ~30.
    # This helps prevent being outbid by the ~80 strategy.
    if my_budget > 0 and bid < 30.0 and supply >= (MIN_SUPPLY + 0.5 * (MAX_SUPPLY - MIN_SUPPLY)):
        bid = min(my_budget, 40.0)

    # Final clamp to non-negative.
    if bid < 0.0:
        bid = 0.0
    return float(bid)

